/**
 * Placeholder artwork helper.
 *
 * Every image in /data currently points at an architectural line-drawing in
 * /public/images/placeholders (generated by scripts/generate-placeholders.mjs).
 * Replace `src` with real, approved photography as it becomes available and
 * update width/height to match the file. Keep descriptive alt text.
 */
export function placeholder(name, alt) {
  return {
    src: `/images/placeholders/${name}.svg`,
    alt,
    width: 1600,
    height: 900,
  };
}
